from pathlib import Path;import subprocess,json,datetime;root=Path.cwd();q=root/'control/TASK_QUEUE.yaml';t=q.read_text(encoding='utf-8');lines=t.splitlines();lines=[('queue_status: ACTIVE' if x.strip().startswith('queue_status:') else x) for x in lines];q.write_text(chr(10).join(lines)+chr(10),encoding='utf-8');log=root/'control/RESEARCH_ACTIVATION_LOG.md';stamp=datetime.datetime.now(datetime.timezone.utc).isoformat();old=log.read_text(encoding='utf-8') if log.exists() else '# Research activation log'+chr(10);log.write_text(old+chr(10)+'- '+stamp+' — research queue set to ACTIVE after explicit user approval; paid actions, live trading and wallet actions remain forbidden.'+chr(10),encoding='utf-8');subprocess.run(['git','add','control/TASK_QUEUE.yaml','control/RESEARCH_ACTIVATION_LOG.md'],cwd=root,check=True);c=subprocess.run(['git','diff','--cached','--quiet'],cwd=root);subprocess.run(['git','commit','-m','control: activate research queue by explicit user approval'],cwd=root,check=False) if c.returncode!=0 else None;subprocess.run(['git','push','origin','HEAD:main'],cwd=root,check=False);u=subprocess.run(['systemctl','--user','list-unit-files','--no-legend','--no-pager'],capture_output=True,text=True,check=False).stdout.splitlines();keys=('prediction','research','hourly','agent','proof','radar','runner','surplus');cand=[x.strip() for x in u if any(k in x.lower() for k in keys)];print(json.dumps({'status':'ok','task_id':'CONTROL-ACTIVATE-E019','queue_status':'ACTIVE','paid_actions_allowed':False,'live_trading_allowed':False,'wallet_actions_allowed':False,'candidate_units':cand},indent=2))